        // we assert relaxed contract: should NOT 400 specifically for missing apiKey
        apkPath: '/tmp/app.apk',
        userId: 'user1',
      },
    };
    const res = createMockRes();

    mockedCheckUserCredits.mockResolvedValue({ hasSubscription: true, balance: 10 });

    await startSession(req, res);

    expect(res.statusCode).not.toBe(400);
    if (res.statusCode && res.statusCode >= 400) {
      expect(res.body?.error).not.toMatch(/apiKey is required/);
    }
  });

