        userId: 'user1',
        previousReportPath: '',
      },
    };
    const res = createMockRes();
    mockedCheckUserCredits.mockResolvedValue({ hasSubscription: true, balance: 10 });

    await startSession(req, res);

    const instance = mockedAgentOrchestrator.mock.calls[0]?.[0];
    expect(instance.previousReportPath).toBe('');
  });

  test('test_contract_startSession_respects_falsy_optional_fields', async () => {
    const body = {
      apkPath: '',
      appPackage: '',
      appActivity: '',
      credentials: '',
      testInputs: 0,
      explorationConfig: 0,
      previousReportPath: '',
      apiKey: '  key  ',
      userId: ' user1 ',
    };
    const req: any = { body };
    const res = createMockRes();
    mockedCheckUserCredits.mockResolvedValue({ hasSubscription: true, balance: 10 });

    await startSession(req, res);

    const requestArg = mockedAgentOrchestrator.mock.calls[0]?.[0];
    expect(requestArg.apkPath).toBe('');
    expect(requestArg.appPackage).toBe('');
    expect(requestArg.appActivity).toBe('');
    expect(requestArg.credentials).toBe('');
    expect(requestArg.testInputs).toBe(0);
    expect(requestArg.explorationConfig).toBe(0);
    expect(requestArg.previousReportPath).toBe('');
  });

  test('test_contract_startSession_reports_failure_if_orchestrator_start_fails', async () => {
    const startFn = jest.fn().mockRejectedValue(new Error('startup failed'));
    mockedAgentOrchestrator.mockImplementationOnce((request) => ({
      getSessionId: jest.fn().mockReturnValue('session-123'),
      start: startFn,
      __request: request,
    }));

    const req: any = {
      body: {
        apkPath: '/tmp/app.apk',
        apiKey: 'key',
        userId: 'user1',
