describe('test_invariant_startSession', () => {
  test('test_invariant_startSession_requires_non_empty_userId_before_credit_checks', async () => {
    const cases = [undefined, null, '', '   ', 123];
    for (const userId of cases as any[]) {
      const req: any = {
        body: {
          apkPath: '/tmp/app.apk',
          apiKey: 'key',
          userId,
        },
      };
      const res = createMockRes();

      await startSession(req, res);

      expect(res.statusCode).toBe(400);
      expect(res.body?.error).toMatch(/userId is required/i);
      expect(mockedCheckUserCredits).not.toHaveBeenCalled();
      mockedCheckUserCredits.mockClear();
    }
  });

  test('test_invariant_startSession_requires_non_empty_apiKey_before_request_construction', async () => {
    const cases = [undefined, null, '', '   ', 123];
    for (const apiKey of cases as any[]) {
      const req: any = {
        body: {
          apkPath: '/tmp/app.apk',
          apiKey,
          userId: 'user1',
        },
      };
      const res = createMockRes();

      await startSession(req, res);

      expect(res.statusCode).toBe(400);
      expect(res.body?.error).toMatch(/apiKey is required/i);
      expect(mockedCheckUserCredits).not.toHaveBeenCalled();
      mockedCheckUserCredits.mockClear();
    }
  });

  test('test_invariant_startSession_requires_valid_routing_strategy', async () => {
    const invalidCases = [
      {}, // no routing
      { apkPath: undefined, appPackage: undefined, appActivity: undefined },
      { appPackage: 'pkg.only' },
      { appActivity: 'activity.only' },
      { apkPath: null },
    ];
    for (const routingBody of invalidCases) {
      const req: any = {
        body: {
          ...routingBody,
          apiKey: 'key',
          userId: 'user1',
        },
      };
      const res = createMockRes();

      await startSession(req, res);

      expect(res.statusCode).toBe(400);
      expect(res.body?.error).toMatch(/Provide either apkPath or both appPackage \+ appActivity/);
      expect(mockedAgentOrchestrator).not.toHaveBeenCalled();
    }

    const validCases = [
      { apkPath: '/tmp/app.apk' },
      { appPackage: 'pkg', appActivity: 'Act' },
    ];
    mockedCheckUserCredits.mockResolvedValue({ hasSubscription: true, balance: 10 });
    for (const routingBody of validCases) {
      const req: any = {
        body: {
          ...routingBody,
          apiKey: 'key',
          userId: 'user1',
        },
      };
      const res = createMockRes();

      await startSession(req, res);

      expect(res.statusCode).toBe(202);
      mockedAgentOrchestrator.mockClear();
    }
  });

  test('test_invariant_startSession_requires_positive_credits_and_active_subscription', async () => {
    const baseBody = {
      apkPath: '/tmp/app.apk',
      apiKey: 'key',
      userId: 'user1',
    };

    const res1 = createMockRes();
    mockedCheckUserCredits.mockResolvedValueOnce({ hasSubscription: false, balance: 100 });
    await startSession({ body: baseBody } as any, res1);
    expect(res1.statusCode).toBe(402);
    expect(res1.body?.error).toMatch(/No active subscription/i);
    expect(mockedAgentOrchestrator).not.toHaveBeenCalled();

    const res2 = createMockRes();
    mockedCheckUserCredits.mockResolvedValueOnce({ hasSubscription: true, balance: 0 });
    await startSession({ body: baseBody } as any, res2);
    expect(res2.statusCode).toBe(402);
    expect(res2.body?.error).toMatch(/Insufficient credits/i);
    expect(mockedAgentOrchestrator).not.toHaveBeenCalled();
  });

  test('test_invariant_startSession_aborts_on_credit_gateway_failure', async () => {
    const req: any = {
      body: {
        apkPath: '/tmp/app.apk',
        apiKey: 'key',
        userId: 'user1',
      },
    };
    const res = createMockRes();
    const loggerInstance = mockedCreateLogger.mock.results[0]?.value || createLogger('test');
    const errorSpy = loggerInstance.error || mockedCreateLogger.mock.results[0]?.value?.error;

    mockedCheckUserCredits.mockRejectedValueOnce(new Error('network down'));

    await startSession(req, res);

    expect(res.statusCode).toBe(503);
    expect(res.body?.error).toMatch(/Unable to verify subscription status/i);
    expect(mockedAgentOrchestrator).not.toHaveBeenCalled();
    if (errorSpy) {
      expect(errorSpy).toHaveBeenCalled();
    }
  });

  test('test_invariant_startSession_does_not_start_orchestrator_on_non_2xx', async () => {
    const req: any = {
      body: {
        apiKey: '', // force 400
        apkPath: '/tmp/app.apk',
        userId: 'user1',
      },
    };
    const res = createMockRes();

    await startSession(req, res);

    expect(res.statusCode).toBe(400);
    expect(mockedAgentOrchestrator).not.toHaveBeenCalled();
  });

  test('test_invariant_startSession_202_response_includes_sessionId', async () => {
    mockedCheckUserCredits.mockResolvedValue({ hasSubscription: true, balance: 10 });

    const req: any = {
      body: {
        apkPath: '/tmp/app.apk',
        apiKey: 'key',
        userId: 'user1',
      },
