    await startSession(req, res);

    expect(res.statusCode).toBe(202);
    expect(res.body?.success).toBe(true);
    expect(res.body?.data?.sessionId).toBeDefined();
    expect(typeof res.body.data.sessionId).toBe('string');
  });
});

