import { initWebSocketServer, broadcast, waitForHumanInput } from './WebSocketManager';
import { WSEventType } from '../types/types';

const getMockWSS = (): any => {
  const WSModule = jest.requireMock('ws');
  const instances = (WSModule.WebSocketServer as any).mock?.instances;
  return instances && instances[0];
};

describe('WebSocketManager', () => {
  beforeEach(() => {
    jest.useFakeTimers();
    jest.clearAllMocks();
  });

  afterEach(() => {
    jest.useRealTimers();
  });

  // ────────────────────────────────────────────────────────────
  // Contract tests
  // ────────────────────────────────────────────────────────────

  test('test_contract_initWebSocketServer_uses_event_field_for_inbound_protocol', () => {
    initWebSocketServer(8080);
    const wss: any = getMockWSS();
    const ws = new WebSocket() as any;

    wss.simulateConnection(ws);

    const message = { event: 'SUBSCRIBE', sessionId: 's1' };
    ws.emit('message', Buffer.from(JSON.stringify(message)));

    const confirmationRaw = ws.sent[0];
    expect(confirmationRaw).toBeDefined();
    const confirmation = JSON.parse(confirmationRaw);
    expect(confirmation).toMatchObject({
      event: 'SUBSCRIBED',
      sessionId: 's1',
    });
  });

  test('test_contract_initWebSocketServer_supports_consistent_discriminator_and_case', () => {
    initWebSocketServer(8081);
    const wss: any = getMockWSS();
    const ws = new WebSocket() as any;

    wss.simulateConnection(ws);

    const msg1 = { action: 'subscribe', sessionId: 's2' };
    const msg2 = { type: 'SUBSCRIBE', sessionId: 's3' };

    ws.emit('message', Buffer.from(JSON.stringify(msg1)));
    ws.emit('message', Buffer.from(JSON.stringify(msg2)));

    expect(ws.sent.length).toBeGreaterThanOrEqual(2);
    const parsed = ws.sent.map(s => JSON.parse(s));
    expect(parsed).toEqual(
      expect.arrayContaining([
        expect.objectContaining({ event: 'SUBSCRIBED', sessionId: 's2' }),
        expect.objectContaining({ event: 'SUBSCRIBED', sessionId: 's3' }),
      ]),
    );
  });

  test('test_contract_initWebSocketServer_unsubscribe_cleans_empty_sessions', () => {
    initWebSocketServer(8082);
    const wss: any = getMockWSS();
    const ws = new WebSocket() as any;

    wss.simulateConnection(ws);

    const subscribeMsg = { action: 'SUBSCRIBE', sessionId: 'sess-cleanup' };
    ws.emit('message', Buffer.from(JSON.stringify(subscribeMsg)));

    const unsubscribeMsg = { action: 'UNSUBSCRIBE', sessionId: 'sess-cleanup' };
    ws.emit('message', Buffer.from(JSON.stringify(unsubscribeMsg)));

    // Expect no lingering subscriptions for that session
    // We verify via broadcast: nothing should be sent because session was removed.
    const event: WSEventType = 'SCREENSHOT_FRAME' as any;
    broadcast('sess-cleanup', event, { foo: 'bar' });
    expect(ws.sent.length).toBe(1); // only SUBSCRIBED confirmation, no broadcast
  });

  test('test_contract_waitForHumanInput_uses_values_field_from_response_payload', async () => {
    initWebSocketServer(8083);
    const wss: any = getMockWSS();
    const ws = new WebSocket() as any;
    wss.simulateConnection(ws);

    const requestId = 'r1';
    const promise = waitForHumanInput(requestId);

    const inbound = {
      event: 'HUMAN_INPUT_RESPONSE',
      requestId,
      payload: { values: { a: '1', b: '2' } },
    };
    ws.emit('message', Buffer.from(JSON.stringify(inbound)));

    const result = await promise;
